```json
{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('SELECT ts.route_stations','SELECT ts.route_distances','Transaction.commit','SELECT ts.route') GROUP BY 1,2 ORDER BY 2", "claim": "ts-route-service DB spans (route_stations, route_distances, route, Transaction.commit) have p95 of about 420–900 ms in the abnormal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM normal_traces WHERE service_name='ts-route-service' AND span_name IN ('SELECT ts.route_stations','SELECT ts.route_distances','Transaction.commit','SELECT ts.route') GROUP BY 1,2 ORDER BY 2", "claim": "The same route-service DB spans run at p95 of about 0.1–0.3 ms in the normal period."},
        {"kind": "trace", "sql": "WITH slow AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name='GET /api/v1/routeservice/routes/{start}/{end}' ORDER BY duration DESC LIMIT 1) SELECT service_name, span_name, span_id, parent_span_id, duration/1e6 ms, attr_k8s_pod_name FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM slow) ORDER BY duration DESC", "claim": "In a slow route request, the route-service handler is about 6.2 s, dominated by a 3.1 s SELECT ts.route_stations inside it."},
        {"kind": "metric", "sql": "SELECT service_name, metric, avg(value) v FROM abnormal_metrics WHERE service_name='ts-route-service' AND metric IN ('container.cpu.usage','k8s.pod.memory.working_set') GROUP BY 1,2", "claim": "Route-service CPU and memory stay flat or lower during the incident, so this is not container saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-route-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "WITH slow AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name LIKE '%minStopStations' ORDER BY duration DESC LIMIT 1) SELECT service_name, span_name, parent_span_id, span_id, duration/1e6 ms, attr_status_code, attr_k8s_pod_name FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM slow) ORDER BY duration DESC", "claim": "Route-plan's outbound GET to route-service takes about 5.9 s, and its own work is only about 6 ms."}]},
    {"from": "ts-route-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-route-service') AND span_name LIKE '%routes%' GROUP BY 1,2 ORDER BY 1,2", "claim": "UI dashboard's /routes requests slow to about 15.7 s p95, matching route-service's slow /routes handling."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-route-plan-service') AND span_name LIKE '%minStation%' GROUP BY 1,2 ORDER BY 1,2", "claim": "Travel-plan minStation requests take about 6.1 s p95, wrapping route-plan's minStopStations calls of about 5.6 s."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "WITH slow AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name LIKE '%minStopStations' ORDER BY duration DESC LIMIT 1) SELECT service_name, span_name, parent_span_id, span_id, duration/1e6 ms FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM slow) AND service_name IN ('ts-ui-dashboard','ts-travel-plan-service') ORDER BY duration DESC", "claim": "In the same slow trace, ui-dashboard's minStation call wraps travel-plan's 5.9 s handler."}]}
  ]
}
